      ctx.strokeStyle = color; ctx.lineWidth = 1.8; ctx.lineJoin = 'round';
      ctx.beginPath();
      s.points.forEach((p, i) => {
        const x = PAD.left + xStep * i;
        const y = PAD.top + h - ((p.value - minVal) / range) * h;
